// Codeforces Daily Tracker - JavaScript

// CORS Proxy - Codeforces API لا يدعم CORS مباشرة
const CORS_PROXY = 'https://corsproxy.io/?';
const CF_API_BASE = 'https://codeforces.com/api';

// Get today's date in YYYY-MM-DD format
function getTodayDate() {
    const today = new Date();
    return today.toISOString().split('T')[0];
}

// Initialize date input with today's date
document.addEventListener('DOMContentLoaded', () => {
    const dateInput = document.getElementById('dateInput');
    dateInput.value = getTodayDate();
    
    // Allow Enter key to trigger search
    document.getElementById('handleInput').addEventListener('keypress', (e) => {
        if (e.key === 'Enter') searchUser();
    });
});

// Show loading state
function setLoading(isLoading) {
    const btn = document.getElementById('searchBtn');
    const loader = document.getElementById('loader');
    const btnText = btn.querySelector('.btn-text');
    
    if (isLoading) {
        btn.disabled = true;
        loader.classList.add('active');
        btnText.textContent = 'جاري البحث...';
    } else {
        btn.disabled = false;
        loader.classList.remove('active');
        btnText.textContent = 'بحث';
    }
}

// Show error message
function showError(message) {
    const errorDiv = document.getElementById('errorMessage');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    document.getElementById('results').classList.add('hidden');
}

// Hide error message
function hideError() {
    document.getElementById('errorMessage').classList.add('hidden');
}

// Format verdict in Arabic
function formatVerdict(verdict) {
    const verdicts = {
        'OK': '✅ مقبول',
        'WRONG_ANSWER': '❌ إجابة خاطئة',
        'TIME_LIMIT_EXCEEDED': '⏱️ تجاوز الوقت',
        'MEMORY_LIMIT_EXCEEDED': '💾 تجاوز الذاكرة',
        'RUNTIME_ERROR': '💥 خطأ في التشغيل',
        'COMPILATION_ERROR': '🔧 خطأ في الترجمة',
        'PRESENTATION_ERROR': '📝 خطأ في العرض',
        'IDLENESS_LIMIT_EXCEEDED': '⏸️ تجاوز حد الخمول',
        'SECURITY_VIOLATED': '🔒 انتهاك أمني',
        'CRASHED': '💔 انهيار',
        'INPUT_PREPARATION_CRASHED': '📥 انهيار تحضير المدخلات',
        'CHALLENGED': '⚔️ تم التحدي',
        'SKIPPED': '⏭️ تم التخطي',
        'TESTING': '🔄 جاري الاختبار',
        'REJECTED': '🚫 مرفوض',
        'PARTIAL': '🔶 قبول جزئي',
        'ACCEPTED': '✅ مقبول',
        'UNKNOWN': '❓ غير معروف'
    };
    return verdicts[verdict] || verdict;
}

// Get verdict class
function getVerdictClass(verdict) {
    return verdict === 'OK' ? 'accepted' : 'wrong';
}

// Format date
function formatDate(timestamp) {
    const date = new Date(timestamp * 1000);
    return date.toLocaleDateString('ar-EG', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
}

// Main search function
async function searchUser() {
    const handle = document.getElementById('handleInput').value.trim();
    const selectedDate = document.getElementById('dateInput').value;
    
    // Validation
    if (!handle) {
        showError('⚠️ الرجاء إدخال اسم الهاندل');
        return;
    }
    
    if (!selectedDate) {
        showError('⚠️ الرجاء اختيار التاريخ');
        return;
    }
    
    hideError();
    setLoading(true);
    
    try {
        // Fetch user submissions from Codeforces API
        // user.status returns all submissions for a user [citation:7][citation:12]
        const apiUrl = `${CF_API_BASE}/user.status?handle=${encodeURIComponent(handle)}`;
        const response = await fetch(CORS_PROXY + encodeURIComponent(apiUrl));
        
        if (!response.ok) {
            throw new Error('فشل الاتصال بالخادم');
        }
        
        const data = await response.json();
        
        // Check API response status [citation:1][citation:3]
        if (data.status === 'FAILED') {
            throw new Error(data.comment || 'فشل في جلب البيانات. تأكد من صحة اسم الهاندل.');
        }
        
        // Process submissions
        processSubmissions(data.result, selectedDate, handle);
        
    } catch (error) {
        console.error('Error:', error);
        
        if (error.message.includes('Failed to fetch')) {
            showError('🔌 فشل الاتصال بالخادم. قد يكون هناك مشكلة في الشبكة أو وكيل CORS. حاول مرة أخرى.');
        } else if (error.message.includes('not found') || error.message.includes('handle')) {
            showError('👤 لم يتم العثور على المستخدم. تأكد من صحة اسم الهاندل.');
        } else {
            showError('❌ ' + error.message);
        }
    } finally {
        setLoading(false);
    }
}

// Process submissions and filter by date
function processSubmissions(submissions, selectedDate, handle) {
    // Filter submissions for the selected date
    const targetDate = new Date(selectedDate);
    targetDate.setHours(0, 0, 0, 0);
    
    const nextDay = new Date(targetDate);
    nextDay.setDate(nextDay.getDate() + 1);
    
    const targetTimestamp = Math.floor(targetDate.getTime() / 1000);
    const nextDayTimestamp = Math.floor(nextDay.getTime() / 1000);
    
    // Filter submissions for the selected day
    const daySubmissions = submissions.filter(sub => {
        const subTime = sub.creationTimeSeconds;
        return subTime >= targetTimestamp && subTime < nextDayTimestamp;
    });
    
    if (daySubmissions.length === 0) {
        showError(`📭 لا توجد محاولات للمستخدم "${handle}" بتاريخ ${selectedDate}`);
        return;
    }
    
    // Separate solved and wrong submissions
    const solvedProblems = [];
    const wrongProblems = [];
    const uniqueSolvedProblems = new Set();
    const uniqueWrongProblems = new Set();
    
    daySubmissions.forEach(sub => {
        const problemInfo = {
            name: sub.problem.name,
            index: sub.problem.index,
            contestId: sub.problem.contestId,
            rating: sub.problem.rating || 'غير محدد',
            tags: sub.problem.tags || [],
            verdict: sub.verdict,
            language: sub.programmingLanguage,
            time: sub.creationTimeSeconds,
            problemUrl: `https://codeforces.com/problemset/problem/${sub.problem.contestId}/${sub.problem.index}`
        };
        
        if (sub.verdict === 'OK') {
            solvedProblems.push(problemInfo);
            uniqueSolvedProblems.add(`${sub.problem.contestId}-${sub.problem.index}`);
        } else {
            wrongProblems.push(problemInfo);
            uniqueWrongProblems.add(`${sub.problem.contestId}-${sub.problem.index}`);
        }
    });
    
    // Update statistics
    document.getElementById('solvedCount').textContent = solvedProblems.length;
    document.getElementById('wrongCount').textContent = wrongProblems.length;
    document.getElementById('totalCount').textContent = daySubmissions.length;
    document.getElementById('uniqueCount').textContent = uniqueSolvedProblems.size;
    
    // Render solved problems
    renderProblems('solvedProblems', solvedProblems, true);
    
    // Render wrong problems
    renderProblems('wrongProblems', wrongProblems, false);
    
    // Show results
    document.getElementById('results').classList.remove('hidden');
}

// Render problems list
function renderProblems(containerId, problems, isSolved) {
    const container = document.getElementById(containerId);
    
    if (problems.length === 0) {
        container.innerHTML = `
            <div class="empty-state">
                <span class="icon">${isSolved ? '📝' : '🎉'}</span>
                <p>${isSolved ? 'لا توجد مسائل محلولة في هذا اليوم' : 'لا توجد محاولات خاطئة في هذا اليوم'}</p>
            </div>
        `;
        return;
    }
    
    // Sort by time
    problems.sort((a, b) => a.time - b.time);
    
    container.innerHTML = problems.map(problem => `
        <div class="problem-item ${isSolved ? 'solved-item' : 'wrong-item'}">
            <div class="problem-info">
                <a href="${problem.problemUrl}" target="_blank" class="problem-name">
                    ${problem.contestId}${problem.index} - ${problem.name}
                </a>
                <div class="problem-meta">
                    ${problem.rating !== 'غير محدد' ? `<span class="problem-rating">⭐ ${problem.rating}</span>` : ''}
                    <span>💻 ${problem.language}</span>
                    <span>🕐 ${formatDate(problem.time)}</span>
                </div>
                ${problem.tags.length > 0 ? `
                    <div class="problem-tags">
                        ${problem.tags.slice(0, 5).map(tag => `<span class="tag">${tag}</span>`).join('')}
                    </div>
                ` : ''}
            </div>
            <span class="verdict-badge ${getVerdictClass(problem.verdict)}">
                ${formatVerdict(problem.verdict)}
            </span>
        </div>
    `).join('');
}

// Export functions for global access
window.searchUser = searchUser;